def resolve(self, path: str, follow: bool = True,
            _depth: int = 0) -> ExtInode:
    """Yolu inode'a cozer.

    `follow` ise ara ve son sembolik baglar izlenir. Bag hedefi goreli
    olabilir (`../usr/lib/os-release`), bu yuzden o ana kadarki dizine gore
    cozulur. Donguye karsi derinlik sinirlidir.
    """
    if _depth > 16:
        raise ExtError(f"Sembolik bag dongusu: {path}")
    node = self.read_inode(INO_ROOT)
    parcalar = [p for p in path.replace("\\", "/").split("/") if p]
    for i, part in enumerate(parcalar):
        if not node.is_dir:
            raise ExtError(f"Dizin degil: {part}")
        for entry in self.read_dir(node):
            if entry.name == part:
                node = self.read_inode(entry.inode)
                break
        else:
            raise ExtError(f"Bulunamadi: {path}")
        if node.is_symlink and (follow or i < len(parcalar) - 1):
            hedef = self.symlink_target(node)
            if hedef.startswith("/"):
                yeni = hedef
            else:
                onceki = "/".join(parcalar[:i])
                yeni = f"/{onceki}/{hedef}" if onceki else f"/{hedef}"
            kalan = parcalar[i + 1:]
            if kalan:
                yeni = yeni.rstrip("/") + "/" + "/".join(kalan)
            return self.resolve(_normalize(yeni), follow=follow,
                                _depth=_depth + 1)
    return node

